    verify_sidecar_not_from_future_slot(chain, column_slot)?;              // step 3: future slot
    verify_slot_greater_than_latest_finalized_slot(chain, column_slot)?;   // step 4: finality
    verify_is_unknown_sidecar(chain, &data_column)?;                       // step 5: dedup
    // step 6: check DA cache
    if chain.data_availability_checker.is_data_column_cached(&data_column.block_root(), &data_column) {
        observe_gossip_data_column(&data_column, chain)?;
        return Err(GossipDataColumnError::PriorKnownUnpublished);
    }
    verify_column_inclusion_proof(&data_column)?;                          // step 7: inclusion proof
    let parent_block = verify_parent_block_and_finalized_descendant(data_column.clone(), chain)?; // step 8
    verify_slot_higher_than_parent(&parent_block, column_slot)?;           // step 9
    verify_proposer_and_signature(&data_column, &parent_block, chain)?;    // step 10: proposer sig
    let kzg = &chain.kzg;
    let kzg_verified_data_column = verify_kzg_for_data_column(data_column.clone(), kzg)
        .map_err(|(_, e)| GossipDataColumnError::InvalidKzgProof(e))?;    // step 11: KZG
    // step 12: observe slashable
    chain.observed_slashable.write().observe_slashable(..).map_err(..)?;
    if O::observe() { observe_gossip_data_column(&data_column, chain)?; }  // step 13: observe
    Ok(GossipVerifiedDataColumn::new(kzg_verified_data_column, ..))
}

