pub fn process_withdrawals<E: EthSpec, Payload: AbstractExecPayload<E>>(
    state: &mut BeaconState<E>,
    payload: Payload::Ref<'_>,
    spec: &ChainSpec,
) -> Result<(), BlockProcessingError> {
    if state.fork_name_unchecked().capella_enabled() {
        let (expected_withdrawals, _) = get_expected_withdrawals(state, spec)?;
        let expected_root = expected_withdrawals.tree_hash_root();
        let withdrawals_root = payload.withdrawals_root()?;
        if expected_root != withdrawals_root {
            return Err(BlockProcessingError::WithdrawalsRootMismatch {
                expected: expected_root,
                found: withdrawals_root,
            });
        }
        // Apply withdrawals to CL validator balances
        for withdrawal in expected_withdrawals.iter() {
            decrease_balance(state, withdrawal.validator_index as usize, withdrawal.amount)?;
        }
    }
    Ok(())
}

